# Creating a Shared Library (libmyapi.so)
gcc -c -fPIC source.c -o source.o
gcc -shared source.o -o libmyapi.so


# Linking Executable Against Library (Runtime Linkage)
# '-L.': Search current dir for library
# '-lmyapi': Link against libmyapi.so
gcc main.c -L. -lmyapi -o application

# Ensuring Runtime Visibility (Crucial for Execution)
export LD_LIBRARY_PATH=$PWD:$LD_LIBRARY_PATH

# Verification of Dynamic Dependencies
ldd ./application


# Manual Dynamic Loading (dlopen API - C)
void *handle;
void (*func)(void);

// Load the library
handle = dlopen("libmyapi.so", RTLD_LAZY);
if (!handle) { /* handle error */ }

// Get function pointer
func = (void (*)(void)) dlsym(handle, "public_func");
if (dlerror() != NULL) { /* handle error */ }

// Use the function
func();

// Unload
dlclose(handle);
